-- NW HUB: SAFE REMOTE WRAPPER + CLIENT-CHECK KICK SUPPRESSOR

-- =====================================================================

pcall(function()

    -- 1. Hook ClientCheck.OnClientEvent to suppress desync kicks

    local rep = game:GetService("ReplicatedStorage")

    local remotesFolder = rep:WaitForChild("Remotes", 8)

    local clientCheckRE = remotesFolder and remotesFolder:WaitForChild("ClientCheck", 8)

    if clientCheckRE and type(getconnections) == "function" then

        for _, conn in ipairs(getconnections(clientCheckRE.OnClientEvent)) do

            if conn.Function and type(hookfunction) == "function" then

                local oldFn = conn.Function

                local upvs = type(getupvalues) == "function" and getupvalues(oldFn)

                local u2 = upvs and upvs[1]

                if type(u2) == "table" then

                    hookfunction(oldFn, newcclosure(function(p3)

                        if u2[p3] then

                            u2[p3] = nil

                            return

                        end

                        -- Suppress kick on token desync (instead of LocalPlayer:Kick())

                    end))

                end

            end

        end

    end



    -- 2. NW_SafeFireServer routes through the game's official _G.FireServer

    getgenv().NW_SafeFireServer = function(remote, ...)

        if not remote then return end

        local renv = type(getrenv) == "function" and getrenv()

        local gFire = renv and renv._G and renv._G.FireServer

        if type(gFire) == "function" then

            local ok = pcall(gFire, remote, ...)

            if ok then return true end

        end

        -- Fallback: direct call (less safe but better than nothing)

        return pcall(remote.FireServer, remote, ...)

    end

end)





local function CheckExecutorCompatibility()

    local function resolveExecutorName()

        local name = "Unknown"

        if type(identifyexecutor) == "function" then

            local ok, n = pcall(identifyexecutor)

            if ok and type(n) == "string" and n ~= "" then return n end

        end

        if type(getexecutorname) == "function" then

            local ok, n = pcall(getexecutorname)

            if ok and type(n) == "string" and n ~= "" then return n end

        end

        return name

    end



    local execName = resolveExecutorName()

    local lower = execName:lower()



    -- 0. Mobile detection: Always allow mobile executors without blocking or black screens

    local isMobileDevice = false

    pcall(function()

        local uis = game:GetService("UserInputService")

        if uis.TouchEnabled then isMobileDevice = true end

        local ok, p = pcall(function() return uis:GetPlatform() end)

        if ok and (p == Enum.Platform.IOS or p == Enum.Platform.Android) then isMobileDevice = true end

    end)

    if isMobileDevice then

        return true

    end



    -- 1. Explicitly blacklisted executors (Level 3 / Incomplete UNC)

    local blacklisted = {

        "solara", "xeno", "celery", "jjsploit", "vega x", "zorara", "incognito", "shadow"

    }

    local isBlacklisted = false

    for _, bad in ipairs(blacklisted) do

        if lower:find(bad) then

            isBlacklisted = true

            break

        end

    end



    -- 2. Known supported mobile executors (Delta, Codex, Hydrogen, Arceus X, etc.)

    local isMobileSupported = lower:find("delta") or lower:find("codex") or lower:find("hydrogen")

        or lower:find("arceus") or lower:find("fluxus") or lower:find("appleware")

        or (getgenv and (getgenv().delta or getgenv().Delta or getgenv().DELTA_LOADED ~= nil))

        or (type(DELTA) ~= "undefined" and DELTA ~= nil)

        or (type(Delta) ~= "undefined" and Delta ~= nil)



    if isMobileSupported then

        return true

