	local Registry = setmetatable({}, { __mode = "k" })   -- inst -> { prop = themeKey }

	local Corners  = setmetatable({}, { __mode = "k" })   -- UICorner -> rayon de base

	local Fonts    = setmetatable({}, { __mode = "k" })   -- texte -> { role, weight }

	K.Registry, K.Corners, K.Fonts = Registry, Corners, Fonts



	local function New(class, props, children)

		local inst = Instance.new(class)

		local parent

		if type(props) == "table" then

			parent = props.Parent

			for k, v in pairs(props) do

				if k ~= "Parent" then inst[k] = v end

			end

		end

		if children then

			for _, c in ipairs(children) do c.Parent = inst end

		end

		if parent then inst.Parent = parent end

		return inst

	end



	function Library:Register(inst, map)

		if type(map) ~= "table" then return inst end

		local cur = Registry[inst]

		if cur then

			for p, k in pairs(map) do cur[p] = k end

		else

			Registry[inst] = map

		end

		for prop, key in pairs(map) do

			if Theme[key] ~= nil then inst[prop] = Theme[key] end

		end

		return inst

	end



	local function Unregister(inst, prop)

		local map = Registry[inst]

		if map then map[prop] = nil end

	end

	K.Unregister = Unregister



	local function Repaint()

		for inst, map in pairs(Registry) do

			if typeof(inst) == "Instance" and inst.Parent ~= nil then

				for prop, key in pairs(map) do

					local v = Theme[key]

					if v ~= nil then pcall(function() inst[prop] = v end) end

				end

			end

		end

		for _, fn in ipairs(K.ThemeHooks or {}) do pcall(fn) end

	end

	K.Repaint = Repaint

	K.ThemeHooks = {}



	function Library:SetTheme(key, color)

		if key == "Accent" then return Library:SetAccent(color) end

		Theme[key] = color

		Repaint()

	end



	function Library:SetAccent(color, persist)

		if typeof(color) ~= "Color3" then return end

		DeriveAccent(color)

		Repaint()

		if persist then

			Prefs.Accent = { color.R, color.G, color.B }

			K.SavePrefs()

		end

	end



	function Library:Connect(signal, fn)

		local conn = signal:Connect(fn)

		table.insert(Library.Connections, conn)

		return conn

	end



	local function Tween(inst, dur, props, style, dir, delay)

		local d = (dur or 0.18) * (Library.Motion or 1)

		local info = TweenInfo.new(d, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out, 0, false, delay or 0)

		local t = TweenService:Create(inst, info, props)

		t:Play()

		return t

	end



	-- Transition vers une couleur du th├¿me, retenue pour qu'un changement de th├¿me

	-- repeigne l'objet dans son etat courant (et non dans sa couleur de depart).

	local function Paint(inst, dur, prop, key, style)

		local map = Registry[inst]

		if map then map[prop] = key else Registry[inst] = { [prop] = key } end

		local c = Theme[key]

		if c then Tween(inst, dur, { [prop] = c }, style) end

	end

	K.Paint = Paint



	local function Corner(parent, radius)

		local full = radius == "full"

		local c = New("UICorner", {

			CornerRadius = full and UDim.new(1, 0) or UDim.new(0, math.floor((radius or 6) * (Prefs.Radius or 1) + 0.5)),

			Parent = parent,

		})

		if not full then Corners[c] = radius or 6 end

		return c

	end



	function K.SetRadiusScale(k)

		Prefs.Radius = k

		for c, base in pairs(Corners) do

			if c.Parent then c.CornerRadius = UDim.new(0, math.floor(base * k + 0.5)) end

		end

	end



	local function Stroke(parent, key, thickness, transparency)

		local s = New("UIStroke", {

			Thickness = thickness or 1,

			Transparency = transparency or 0,

			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,

			LineJoinMode = Enum.LineJoinMode.Round,

			Parent = parent,

		})

		Library:Register(s, { Color = key or "BorderSoft" })

		return s

	end



	local function Pad(parent, t, b, l, r)

		return New("UIPadding", {

			PaddingTop = UDim.new(0, t or 0), PaddingBottom = UDim.new(0, b or t or 0),

			PaddingLeft = UDim.new(0, l or 0), PaddingRight = UDim.new(0, r or l or 0),

			Parent = parent,

