			if type(cfg) == "table" and type(cfg.Id) == "string" then

				table.insert(list, New("Sound", { SoundId = cfg.Id }))

			end

		end

		pcall(function() ContentProvider:PreloadAsync(list) end)

		for _, s in ipairs(list) do s:Destroy() end

	end)



