	--=====================================================================



	local BlurFx

	local Dim = New("Frame", {

		Name = "Dim",

		BackgroundColor3 = Color3.fromRGB(6, 6, 8),

		BackgroundTransparency = 1,

		BorderSizePixel = 0,

		Size = UDim2.fromScale(1, 1),

		ZIndex = 0,

		Parent = ScreenGui,

	})

	local DimVignette = FxImage(ScreenGui, "vignette", 0)

	DimVignette.Size = UDim2.fromScale(1, 1)

	DimVignette.ImageTransparency = 1



	function FX.GameBlur(on)

		if not Library.Blur or Prefs.Blur == false then on = false end

		Tween(Dim, 0.45, { BackgroundTransparency = on and 0.55 or 1 })

		Tween(DimVignette, 0.45, { ImageTransparency = on and 0.25 or 1 })

		if on and not (BlurFx and BlurFx.Parent) then

			local cam = workspace.CurrentCamera

			if cam then BlurFx = New("BlurEffect", { Name = "KyokaBlur", Size = 0, Parent = cam }) end

		end

		if BlurFx and BlurFx.Parent then Tween(BlurFx, 0.45, { Size = on and 16 or 0 }) end

	end



	function FX.ClearBlur()

		pcall(function() if BlurFx then BlurFx:Destroy() end end)

		BlurFx = nil

	end



	--=====================================================================

	-- Rep├¿res d'aimantation (deplacement de la fen├¬tre)

	--=====================================================================



	local Guides = {}

	for i = 1, 2 do

		local g = New("Frame", {

			Name = "Guide",

			BackgroundColor3 = Color3.new(1, 1, 1),

			BorderSizePixel = 0,

			BackgroundTransparency = 1,

			ZIndex = 858,

			Parent = ScreenGui,

		})

		Library:Register(g, { BackgroundColor3 = "Accent" })

		New("UIGradient", { Rotation = i == 1 and 90 or 0, Transparency = NSeq({ { 0, 1 }, { 0.5, 0 }, { 1, 1 } }), Parent = g })

		Guides[i] = g

	end



	-- axis 1 = trait vertical ├á x, 2 = trait horizontal ├á y ; nil = cache.

	function FX.Guide(axis, value)

		local g = Guides[axis]

		if value == nil then

			if g.BackgroundTransparency < 1 then Tween(g, 0.2, { BackgroundTransparency = 1 }) end

			return

		end

		if axis == 1 then

			g.Size = UDim2.new(0, 1, 1, 0)

			g.Position = UDim2.fromOffset(value, 0)

		else

			g.Size = UDim2.new(1, 0, 0, 1)

			g.Position = UDim2.fromOffset(0, value)

		end

		if g.BackgroundTransparency > 0.5 then Tween(g, 0.12, { BackgroundTransparency = 0.35 }) end

	end



