	function Elements:AddLabel(text, opts)

		opts = opts or {}

		local holder = New("Frame", {

			Name = "LabelRow",

			BackgroundTransparency = 1,

			Size = UDim2.new(1, 0, 0, 24),

			AutomaticSize = opts.Wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.None,

			LayoutOrder = self.NextOrder and self:NextOrder() or 0,

			Parent = self.Container,

		})

		TrackRow(self, holder, text)

		local lbl = Label(holder, text, opts.Size or 13, type(opts.Color) == "string" and opts.Color or "TextDim")

		if typeof(opts.Color) == "Color3" then Unregister(lbl, "TextColor3"); lbl.TextColor3 = opts.Color end

		if opts.Wrap then

			lbl.TextWrapped = true

			lbl.AutomaticSize = Enum.AutomaticSize.Y

			lbl.Size = UDim2.new(1, 0, 0, 0)

			lbl.TextYAlignment = Enum.TextYAlignment.Top

			Pad(holder, 3, 3, 0, 0)

		end

		if opts.Center then lbl.TextXAlignment = Enum.TextXAlignment.Center end

		local obj = { Type = "Label", Label = lbl }

		function obj:SetText(t) lbl.Text = tostring(t or "") end

		function obj:SetColor(c)

			if typeof(c) ~= "Color3" then return end

			Unregister(lbl, "TextColor3")

			lbl.TextColor3 = c

		end

		return obj

	end



	function Elements:AddParagraph(title, body)

		if type(title) == "table" then

			body = title.Content or title.Body or title.Text

			title = title.Title or ""

		end

		local holder = New("Frame", {

			Name = "Paragraph",

			BackgroundTransparency = 1,

			Size = UDim2.new(1, 0, 0, 0),

			AutomaticSize = Enum.AutomaticSize.Y,

			LayoutOrder = self.NextOrder and self:NextOrder() or 0,

			Parent = self.Container,

		})

		Pad(holder, 6, 8, 0, 0)

		List(holder, 3)

		TrackRow(self, holder, tostring(title) .. " " .. tostring(body))

		local t = Label(holder, title, 13.5, "Text", Enum.FontWeight.SemiBold)

		t.Size = UDim2.new(1, 0, 0, 18)

		t.LayoutOrder = 1

		local b = Label(holder, body, 12.5, "TextDim")

		b.TextWrapped = true

		b.AutomaticSize = Enum.AutomaticSize.Y

		b.Size = UDim2.new(1, 0, 0, 0)

		b.TextYAlignment = Enum.TextYAlignment.Top

		b.LayoutOrder = 2

		local obj = { Type = "Paragraph" }

		function obj:SetTitle(v) t.Text = tostring(v) end

		function obj:SetBody(v) b.Text = tostring(v) end

		function obj:Set(v1, v2)

			if v1 ~= nil then t.Text = tostring(v1) end

			if v2 ~= nil then b.Text = tostring(v2) end

		end

		return obj

	end



