			ZIndex = 4,

			Parent = track,

		})

		Library:Register(fill, { BackgroundColor3 = "Accent" })

		Corner(fill, "full")



		local knob = New("Frame", {

			Name = "Knob",

			AnchorPoint = Vector2.new(0.5, 0.5),

			Position = UDim2.fromScale(0, 0.5),

			Size = UDim2.fromOffset(12, 12),

			BackgroundColor3 = Color3.new(1, 1, 1),

			BorderSizePixel = 0,

			ZIndex = 6,

			Parent = track,

		})

		Corner(knob, "full")

		local knobRing = New("UIStroke", { Thickness = 0, Transparency = 0.45, Parent = knob })

		Library:Register(knobRing, { Color = "Accent" })



		-- Bulle au-dessus du bouton pendant le glissement.

		local bubble = New("Frame", {

			AnchorPoint = Vector2.new(0.5, 1),

			Position = UDim2.new(0.5, 0, 0, -8),

			Size = UDim2.fromOffset(0, 20),

			AutomaticSize = Enum.AutomaticSize.X,

			Visible = false,

			ZIndex = 30,

			Parent = knob,

		})

		Library:Register(bubble, { BackgroundColor3 = "Light" })

		Corner(bubble, 5)

		Pad(bubble, 0, 0, 7, 7)

		local bubbleText = Mono(bubble, "", 11, "OnLight", Enum.FontWeight.Bold)

		bubbleText.AutomaticSize = Enum.AutomaticSize.X

		bubbleText.Size = UDim2.new(0, 0, 1, 0)

		bubbleText.ZIndex = 31

		bubbleText.TextXAlignment = Enum.TextXAlignment.Center



		local obj = Bind({ Type = "Slider" }, flag, default)

		obj.Callback = opts.Callback

		obj.Text, obj.Row, obj.Min, obj.Max, obj.Rounding, obj.Suffix = text, row, min, max, rounding, suffix



		local function fmt(v) return tostring(Round(v, rounding)) .. suffix end



		local lastTick = 0

		local function paint(instant)

			local alpha = (max - min) == 0 and 0 or (obj.Value - min) / (max - min)

			local d = instant and 0 or 0.08

			Tween(fill, d, { Size = UDim2.fromScale(alpha, 1) })

			Tween(knob, d, { Position = UDim2.fromScale(alpha, 0.5) })

			if not valueBox:IsFocused() then valueBox.Text = fmt(obj.Value) end

			bubbleText.Text = fmt(obj.Value)

		end



		function obj:Set(value, silent)

			value = math.clamp(Round(tonumber(value) or min, rounding), min, max)

			local changed = value ~= obj.Value

			obj.Value = value

			if flag then Library.Flags[flag] = value end

			paint()

			if changed and not silent then

				if os.clock() - lastTick > 0.045 then

					lastTick = os.clock()

					Library:PlaySound("Tick", { Pitch = 0.85 + ((value - min) / math.max(max - min, 1e-6)) * 0.5 })

				end

				if obj.Callback then task.spawn(obj.Callback, value) end

			end

		end

		function obj:Get() return obj.Value end

		function obj:SetRange(newMin, newMax)

			min, max = newMin or min, newMax or max

			obj.Min, obj.Max = min, max

			obj:Set(obj.Value, true)

		end



		local dragging = false

		local function fromInput(input)

			local x = K.InputPos(input).X

			local a = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)

			obj:Set(min + (max - min) * a)

		end



		local hit = Hit(track, "SliderHit", 8)

		hit.Size = UDim2.new(1, 12, 1, 22)

		hit.Position = UDim2.fromOffset(-6, -11)

		Library:Connect(hit.InputBegan, function(input)

			if IsClick(input) then

				dragging = true

				bubble.Visible = true

				Tween(knob, 0.15, { Size = UDim2.fromOffset(15, 15) }, Enum.EasingStyle.Back)

				Tween(knobRing, 0.15, { Thickness = 4 })

				fromInput(input)

			end

		end)

		Library:Connect(UserInputService.InputEnded, function(input)

			if dragging and IsClick(input) then

				dragging = false

				bubble.Visible = false

				Tween(knob, 0.2, { Size = UDim2.fromOffset(12, 12) }, Enum.EasingStyle.Back)

				Tween(knobRing, 0.2, { Thickness = 0 })

			end

		end)

		Library:Connect(UserInputService.InputChanged, function(input)

			if dragging and IsMove(input) then fromInput(input) end

		end)

		HoverRow(hit, lbl, hover, nil, function()

			if not dragging then Paint(lbl, 0.15, "TextColor3", "TextDim") end

		end)

		BindContext(hit, obj)



		Library:Connect(valueBox.Focused, function()

			valueBox.Text = tostring(Round(obj.Value, rounding))

			Paint(chipStroke, 0.12, "Color", "Accent")

		end)

		Library:Connect(valueBox.FocusLost, function()

			local n = tonumber((valueBox.Text:gsub("[^%d%.%-]", "")))

			if n then obj:Set(n) end

			valueBox.Text = fmt(obj.Value)

			Paint(chipStroke, 0.15, "Color", "BorderSoft")

		end)



		paint(true)

		if opts.Callback and opts.FireOnStart then task.spawn(opts.Callback, obj.Value) end

		return Addonable(obj, addons)

	end



	--=====================================================================

	-- Popups (CanvasGroup : fondu d'un bloc et coins vraiment arrondis)

	--=====================================================================



	local function MakePopup(anchor, width, height)

		local function W() return type(width) == "function" and width() or width end

		local holder = New("Frame", {

			Name = "PopupHolder",

			BackgroundTransparency = 1,

			Size = UDim2.fromOffset(W(), height),

			Visible = false,

			ZIndex = 510,

			Parent = PopupLayer,

		})

		local scale = New("UIScale", { Scale = Factor(), Parent = holder })

		Shadow(holder, 18, 0.45, 509)

		local popup = New("CanvasGroup", {

			Name = "Popup",

			Size = UDim2.fromScale(1, 1),

			GroupTransparency = 1,

			ZIndex = 510,

			Parent = holder,

		})

		Library:Register(popup, { BackgroundColor3 = "Panel2" })

		Corner(popup, 9)

		local border = New("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 540, Parent = holder })

		Corner(border, 9)

		Stroke(border, "Border")



		local slide = 0

		local function reposition()

			local o = PopupLayer.AbsolutePosition

			local ap, as = anchor.AbsolutePosition, anchor.AbsoluteSize

			local vp = ViewportSize()

			local f = Factor()

			local w, h = holder.Size.X.Offset * f, holder.Size.Y.Offset * f

			local x = math.clamp(ap.X - o.X, 6, math.max(vp.X - w - 6, 6))

			local y = ap.Y - o.Y + as.Y + 5

			if y + h > vp.Y - 6 then y = math.max(ap.Y - o.Y - h - 5, 6) end

			holder.Position = UDim2.fromOffset(x, y + slide * f)

		end



		local isOpen, follow = false, nil

		local closeFn

		local function close()

			if not isOpen then return end

			isOpen = false

			if follow then follow:Disconnect(); follow = nil end

			Tween(popup, 0.14, { GroupTransparency = 1 }, Enum.EasingStyle.Quad)

			border.Visible = false

			task.delay(0.15 * Library.Motion, function()

				if not isOpen then holder.Visible = false end

			end)

			if K.GetActivePopup() == closeFn then K.SetActivePopup(nil) end

		end

		closeFn = close



		local function open()

			K.CloseActivePopup()

			isOpen = true

			holder.Size = UDim2.fromOffset(W(), holder.Size.Y.Offset)

			scale.Scale = Factor()

			holder.Visible = true

			border.Visible = true

			popup.GroupTransparency = 1

			slide = -6

			reposition()

			Tween(popup, 0.2, { GroupTransparency = 0 }, Enum.EasingStyle.Quad)

			local t0 = os.clock()

			follow = RunService.RenderStepped:Connect(function()

				local a = math.clamp((os.clock() - t0) / (0.3 * Library.Motion), 0, 1)

				slide = -6 * (1 - a) ^ 3

				reposition()

			end)

			K.SetActivePopup(closeFn)

			Library:PlaySound("Popup")

		end



		local function toggle() if isOpen then close() else open() end end



		Library:Connect(UserInputService.InputBegan, function(input)

			if not isOpen or not IsClick(input) then return end

			local p = MousePos()

			if not K.PointInside(holder, p) and not K.PointInside(anchor, p) then close() end

		end)



		return popup, open, close, toggle, function() return isOpen end, holder

	end

	K.MakePopup = MakePopup



	local function FieldBox(parent, width, height, radius)

		local box = New("Frame", {

			Name = "Field",

			Size = width and UDim2.fromOffset(width, height or M.Field) or UDim2.new(1, 0, 0, height or M.Field),

			ZIndex = 11,

			Parent = parent,

		})

		Library:Register(box, { BackgroundColor3 = "Element" })

		Corner(box, radius or 7)

		local stroke = Stroke(box, "BorderSoft")

		return box, stroke

	end

	K.FieldBox = FieldBox



	local function SearchField(parent, placeholder, z)

		local sb = FieldBox(parent, nil, 28, 6)

		sb.ZIndex = z

		local ic = Icon(sb, "search", 13, "TextFaint", z + 1)

		ic.AnchorPoint = Vector2.new(0, 0.5)

		ic.Position = UDim2.new(0, 9, 0.5, 0)

		local box = New("TextBox", {

			BackgroundTransparency = 1,

			Text = "",

			PlaceholderText = placeholder or "SearchΓÇª",

			TextSize = TS(12.5),

			TextXAlignment = Enum.TextXAlignment.Left,

			ClearTextOnFocus = false,

			Size = UDim2.new(1, -36, 1, 0),

			Position = UDim2.fromOffset(28, 0),

			ZIndex = z + 1,

			Parent = sb,

		})

		SetFontRole(box, "Text", Enum.FontWeight.Medium)

		Library:Register(box, { TextColor3 = "Text", PlaceholderColor3 = "TextFaint" })

		return box, sb

	end

	K.SearchField = SearchField



