	local Page = {}

	Page.__index = Page

	K.Page = Page



	function Page:AddGroup(title, side, opts) return CreateGroup(self, title, side, opts) end

	Page.AddSection = Page.AddGroup

	Page.AddGroupbox = Page.AddGroup

	function Page:AddLeftGroupbox(title) return CreateGroup(self, title, "Left") end

	function Page:AddRightGroupbox(title) return CreateGroup(self, title, "Right") end



	--=====================================================================

	-- Tab

	--=====================================================================



	local Tab = {}

	Tab.__index = Tab

	K.Tab = Tab



	function Tab:AddPage(name)

		local tab = self

		local button = New("TextButton", {

			Name = "Page_" .. name,

			Text = "",

			AutoButtonColor = false,

			BackgroundTransparency = 1,

			Size = UDim2.new(0, 0, 1, 0),

			AutomaticSize = Enum.AutomaticSize.X,

			LayoutOrder = #tab.Pages + 1,

			ZIndex = 22,

			Parent = tab.PageRow,

		})

		Pad(button, 0, 0, 10, 10)

		local btnLabel = Label(button, name, 13, "TextFaint", Enum.FontWeight.SemiBold)

		btnLabel.AutomaticSize = Enum.AutomaticSize.X

		btnLabel.Size = UDim2.new(0, 0, 1, 0)

