	--=====================================================================

	-- Configuration (m├¬me format que Vesper / Kyoka)

	--=====================================================================



	local function Serialize(value)

		if typeof(value) == "Color3" then

			return { __t = "Color3", R = value.R, G = value.G, B = value.B }

		elseif typeof(value) == "EnumItem" then

			return { __t = "Enum", Name = value.Name, Type = tostring(value.EnumType) }

		elseif type(value) == "table" then

			if value.Key ~= nil or value.Mode ~= nil then

				local k = value.Key

				return {

					__t = "Keybind",

					Key = k and (typeof(k) == "EnumItem" and k.Name or tostring(k)) or nil,

					IsMouse = k and typeof(k) == "EnumItem" and tostring(k.EnumType) == "Enum.UserInputType" or false,

					Mode = value.Mode,

				}

			end

			local out = { __t = "List" }

			for i, v in ipairs(value) do out[i] = Serialize(v) end

			return out

		end

		return value

	end



	local function Deserialize(value)

		if type(value) ~= "table" then return value end

		if value.__t == "Color3" then

			return Color3.new(value.R, value.G, value.B)

		elseif value.__t == "Enum" then

			local enumType = value.Type:gsub("Enum%.", "")

			local ok, item = pcall(function() return Enum[enumType][value.Name] end)

			return ok and item or nil

		elseif value.__t == "Keybind" then

			local key

			if value.Key then

				if value.IsMouse then

					key = Enum.UserInputType[value.Key]

				else

					local ok, k = pcall(function() return Enum.KeyCode[value.Key] end)

					key = ok and k or nil

				end

			end

			return { Key = key, Mode = value.Mode }

		elseif value.__t == "List" then

			local out = {}

			for i, v in ipairs(value) do out[i] = Deserialize(v) end

			return out

		end

		return value

	end



	function Library:GetConfig()

		local data = {}

		for flag, option in pairs(Library.Options) do

			if option.Get and option.Type ~= "Button" then

				local ok, v = pcall(option.Get, option)

				if ok then data[flag] = Serialize(v) end

			end

		end

		return data

	end



	function Library:LoadConfig(data)

		if type(data) == "string" then

			local ok, dec = pcall(function() return HttpService:JSONDecode(data) end)

			if not ok then return false end

			data = dec

		end

		if type(data) ~= "table" then return false end

		for flag, raw in pairs(data) do

			local option = Library.Options[flag]

			if option and option.Set then pcall(option.Set, option, Deserialize(raw)) end

		end

		return true

	end



	local function ConfigDir(folder)

		return folder or Library.ConfigFolder or "vesper"

	end



	function Library:SaveConfigToFile(name, folder)

		local dir = ConfigDir(folder)

		if not HasFS() then return false, "file system unavailable" end

		if not isfolder(dir) then makefolder(dir) end

		return pcall(function()

			writefile(dir .. "/" .. name .. ".json", HttpService:JSONEncode(Library:GetConfig()))

		end)

	end



	function Library:LoadConfigFromFile(name, folder)

		local dir = ConfigDir(folder)

		if not HasFS() then return false, "file system unavailable" end

		local path = dir .. "/" .. name .. ".json"

		if not isfile(path) then return false, "config not found" end

		return pcall(function() Library:LoadConfig(HttpService:JSONDecode(readfile(path))) end)

	end



	function Library:ListConfigs(folder)

		local dir = ConfigDir(folder)

		if not HasFS() or not isfolder(dir) or type(listfiles) ~= "function" then return {} end

		local out = {}

		for _, path in ipairs(listfiles(dir)) do

			local name = path:match("([^/\\]+)%.json$")

			if name then table.insert(out, name) end

		end

		return out

	end



	function Library:DeleteConfig(name, folder)

		local path = ConfigDir(folder) .. "/" .. name .. ".json"

		if HasFS() and type(delfile) == "function" and isfile(path) then

			return pcall(delfile, path)

		end

		return false

	end



	--=====================================================================

	-- Kyoka Assist (Ctrl+K)

	-- Recherche globale + commandes en langage naturel, fran├ºais ou anglais :

	--   |½ active l'esp et mets la distance ├á 12 |╗, |½ turn off auto farm |╗,

	--   |½ th├¿me rouge |╗, |½ volume 40 |╗, |½ va dans visuals |╗, |½ save config farm |╗

	-- Tout est compris en local (aucune cle, aucun serveur). Un mod├¿le distant

	-- peut ├¬tre branche avec Kyoka:SetAI({ Endpoint = url }) pour les phrases floues.

	-- Portee propre : le chunk principal approche la limite de locales de Luau.

	--=====================================================================



	;(function()



	local A = {

		Entries = {}, Commands = {}, Pinned = {}, Recent = {},

		Rows = {}, Results = {}, Actions = {}, Index = 1, Shown = false,

	}

	Library.Palette = A

	Library.PaletteKey = Enum.KeyCode.K

	Library.PaletteEnabled = true

	Library.AI = { Endpoint = nil, Headers = {} }



	--=====================================================================

	-- Indexation : on enveloppe les fabriques d'elements

	--=====================================================================



	local KINDS = {

		AddToggle = "toggle", AddSlider = "slider", AddDropdown = "dropdown", AddKeybind = "keybind",

		AddColorPicker = "color", AddTextbox = "textbox", AddButton = "button",

	}

	for name, kind in pairs(KINDS) do

		local orig = Elements[name]

		Elements[name] = function(self, a, b, ...)

			local before = (self.Rows and #self.Rows) or 0

			local obj = orig(self, a, b, ...)

			if self.Internal then return obj end

			local opts = (type(b) == "table" and b) or (type(a) == "table" and a) or {}

			local text = kind == "button" and ((type(a) == "string" and a) or opts.Text or "Button")

				or (opts.Text or opts.Name or (type(a) == "string" and a) or kind)

			local tracked = self.Rows and self.Rows[before + 1]

			local entry = {

				Kind = kind, Text = tostring(text), Obj = obj, Group = self,

				Row = tracked and tracked.Frame or nil,

				Flag = (type(obj) == "table" and obj.Flag) or (kind ~= "button" and type(a) == "string" and a) or nil,

			}

			if type(obj) == "table" then obj.Entry = entry end

			table.insert(A.Entries, entry)

			return obj

		end

	end

	Elements.AddInput = Elements.AddTextbox



	local function PathOf(e)

		local g = e.Group

		local page = g and g.Page

		local tab = page and page.Tab

		local parts = {}

		if tab and tab.Name then table.insert(parts, tab.Name) end

		if page and page.Name and tab and #tab.Pages > 1 then table.insert(parts, page.Name) end

		if g and g.Name then table.insert(parts, g.Name) end

		return table.concat(parts, "  ΓÇ║  ")

	end



	--=====================================================================

	-- Texte : normalisation, similarite

	--=====================================================================



	local ACCENTS = {

		["├á"] = "a", ["├ó"] = "a", ["├ñ"] = "a", ["├í"] = "a", ["e"] = "e", ["├¿"] = "e", ["├¬"] = "e", ["├½"] = "e",

		["├«"] = "i", ["├»"] = "i", ["├¡"] = "i", ["├┤"] = "o", ["├╢"] = "o", ["├│"] = "o", ["o"] = "o",

		["├╣"] = "u", ["├╗"] = "u", ["├╝"] = "u", ["├║"] = "u", ["├º"] = "c", ["├▒"] = "n",

		["├Ç"] = "a", ["├ë"] = "e", ["├ê"] = "e", ["├è"] = "e", ["├ç"] = "c", ["┼î"] = "o",

	}



	local function Norm(s)

		s = tostring(s or "")

		s = s:gsub("[%z\1-\127\194-\244][\128-\191]*", function(c) return ACCENTS[c] or c end)

		s = string.lower(s)

		s = s:gsub("[ΓÇÖ']", " "):gsub("[^%w%.%-%s#]", " "):gsub("%s+", " ")

		return (s:gsub("^%s+", ""):gsub("%s+$", ""))

	end



	local function Tokens(s)

		local out = {}

		for w in Norm(s):gmatch("[^%s]+") do table.insert(out, w) end

		return out

	end



	local function Lev(a, b)

		if a == b then return 0 end

		local la, lb = #a, #b

		if math.abs(la - lb) > 2 then return 3 end

		local prev = {}

		for j = 0, lb do prev[j] = j end

		for i = 1, la do

			local cur = { [0] = i }

			local ca = a:byte(i)

			for j = 1, lb do

				local cost = (ca == b:byte(j)) and 0 or 1

				cur[j] = math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)

			end

			prev = cur

		end

		return prev[lb]

	end



	local function TokSim(q, t)

		if q == t then return 1 end

		if #q >= 2 and t:sub(1, #q) == q then return #q >= 3 and 0.88 or 0.6 end

		if #q >= 3 and t:find(q, 1, true) then return 0.7 end

		if #t >= 3 and q:sub(1, #t) == t then return 0.75 end

		if #q >= 4 then

			local d = Lev(q, t)

			if d == 1 then return 0.78 end

			if d == 2 and #q >= 7 then return 0.6 end

		end

		return 0

	end



	-- Score d'un texte cible pour une liste de mots.

	local function Score(words, text, path)

		if #words == 0 then return 0 end

		local tt, pt = Tokens(text), Tokens(path or "")

		local sum = 0

		for _, w in ipairs(words) do

			local best = 0

			for _, t in ipairs(tt) do best = math.max(best, TokSim(w, t)) end

			for _, t in ipairs(pt) do best = math.max(best, TokSim(w, t) * 0.55) end

			sum += best

		end

		local s = sum / #words

		local nt = Norm(text)

		if nt == table.concat(words, " ") then s += 0.4

		elseif nt:find(table.concat(words, " "), 1, true) then s += 0.2 end

		-- Petit avantage aux textes courts (|½ ESP |╗ plut├┤t que |½ ESP Max Distance |╗).

		return s - #tt * 0.01

	end



	--=====================================================================

	-- Comprehension des phrases

	--=====================================================================



	local VERB = {

		on = { "active", "activer", "activez", "activ", "allume", "allumer", "enable", "enabled", "on", "start", "demarre", "demarrer", "coche", "lance", "lancer", "met en marche", "turn on", "switch on", "ouvre l", "start the" },

		off = { "desactive", "desactiver", "desactivez", "desactiv", "eteins", "eteindre", "coupe", "couper", "disable", "disabled", "off", "stop", "arrete", "arreter", "decoche", "enleve", "retire", "turn off", "switch off" },

		toggle = { "toggle", "bascule", "basculer", "inverse", "inverser", "switch" },

		set = { "mets", "met", "mettre", "regle", "regler", "set", "change", "changer", "passe", "passer", "fixe", "fixer", "ajuste", "ajuster", "put" },

		press = { "clique", "cliquer", "appuie", "appuyer", "press", "click", "run", "execute", "executer", "fais", "faire", "do" },

		go = { "va", "aller", "vas", "go", "ouvre", "ouvrir", "open", "montre", "montrer", "affiche", "afficher", "show", "goto" },

		reset = { "reset", "reinitialise", "reinitialiser", "remet", "remets", "default", "defaut" },

	}

	local FILLER = {}

	for _, w in ipairs({ "le", "la", "les", "l", "de", "du", "des", "d", "un", "une", "the", "a", "an", "my", "mon", "ma", "mes", "to", "sur", "au", "aux", "pour", "en", "et", "of", "in", "dans", "with", "avec", "moi", "me", "please", "stp", "svp", "s", "il", "te", "plait", "valeur", "value", "onglet", "tab", "page", "option", "the", "is", "est", "at", "on", "off", "=", "->", "a" }) do FILLER[w] = true end



	local COLOR_WORDS = {

		violet = "Kyoka", purple = "Kyoka", mauve = "Kyoka", kyoka = "Kyoka", aizen = "Kyoka",

		blanc = "Mono", white = "Mono", mono = "Mono", gris = "Mono", gray = "Mono", grey = "Mono", noir = "Mono", black = "Mono",

		rouge = "Crimson", red = "Crimson", crimson = "Crimson",

		vert = "Jade", green = "Jade", jade = "Jade",

		bleu = "Azure", blue = "Azure", azure = "Azure", cyan = "Azure",

		orange = "Amber", jaune = "Amber", yellow = "Amber", gold = "Amber", ["or"] = "Amber", amber = "Amber",

		rose = "Sakura", pink = "Sakura", sakura = "Sakura",

	}



	local function HasVerb(norm, list)

		local padded = " " .. norm .. " "

		for _, v in ipairs(list) do

			if padded:find(" " .. v .. " ", 1, true) or (v:sub(-1) ~= " " and #v >= 5 and padded:find(" " .. v, 1, true)) then

				return v

			end

		end

		return nil

	end



	local function StripWords(norm, verbs)

		local words = {}

		local skip = {}

		for _, list in pairs(VERB) do

			for _, v in ipairs(list) do

				if not v:find(" ") then skip[v] = true end

			end

		end

		for w in norm:gmatch("[^%s]+") do

			local isNum = tonumber((w:gsub(",", "."))) ~= nil

			local stem = false

			for v in pairs(skip) do

				if #v >= 5 and w:sub(1, #v) == v then stem = true break end

			end

			if not FILLER[w] and not skip[w] and not stem and not isNum and not w:match("^%d+[%%%a]*$") then

				table.insert(words, w)

			end

		end

		local _ = verbs

		return words

	end



	local function FirstNumber(s)

		local n = s:match("(%-?%d+[%.,]?%d*)")

		if not n then return nil end

		return tonumber((n:gsub(",", ".")))

	end



	local function BestEntry(words, kinds)

		local best, bestScore = nil, 0

		for _, e in ipairs(A.Entries) do

			if (not kinds or kinds[e.Kind]) and e.Row and e.Row.Parent then

				local s = Score(words, e.Text, PathOf(e))

				if s > bestScore then best, bestScore = e, s end

			end

		end

		return best, bestScore

	end



	local function Describe(e) return ('<b>%s</b>'):format(e.Text) end



	-- Une proposition par morceau de phrase.

	local function ParseClause(raw)

		local norm = Norm(raw)

		if norm == "" then return nil end

		local num = FirstNumber(norm)



		-- Reglages de l'interface d'abord.

		if norm:find("theme") or norm:find("couleur") or norm:find("color") or norm:find("accent") then

			for w in norm:gmatch("[^%s]+") do

				local preset = COLOR_WORDS[w]

				if preset then

					return { Label = ('Theme ΓåÆ <b>%s</b>'):format(preset), Icon = "palette", Run = function()

						for _, p in ipairs(Library.Presets) do

							if p.Name == preset then Library:SetAccent(p.Accent, true) end

						end

					end }

				end

			end

		end

		if (norm:find("volume") or norm:find("son") or norm:find("sound")) and num then

			return { Label = ('Volume ΓåÆ <b>%d%%</b>'):format(math.clamp(num, 0, 100)), Icon = "volume", Run = function()

				Prefs.Volume = math.clamp(num, 0, 100) / 100 * 1.2

				Prefs.Sound = num > 0

				K.SavePrefs()

				Library:PlaySound("Click")

			end }

		end

		if norm:find("mute") or norm:find("coupe le son") or norm:find("sans son") or norm:find("silence") then

			return { Label = "Mute all sounds", Icon = "mute", Run = function() Prefs.Sound = false; K.SavePrefs() end }

		end

		if (norm:find("save") or norm:find("sauvegarde") or norm:find("enregistre")) and (norm:find("config") or norm:find("preset") or norm:find("profil")) then

			local name = norm:match("config%s+([%w_%-]+)") or norm:match("preset%s+([%w_%-]+)") or norm:match("profil%s+([%w_%-]+)") or "default"

			return { Label = ('Save config <b>%s</b>'):format(name), Icon = "save", Run = function()

				local ok = Library:SaveConfigToFile(name)

				Library:Notify({ Title = "Config", Content = ok and ("Saved as " .. name .. ".") or "No file system here.", Type = ok and "success" or "error" })

			end }

		end

		if (norm:find("load") or norm:find("charge")) and (norm:find("config") or norm:find("preset") or norm:find("profil")) then

			local name = norm:match("config%s+([%w_%-]+)") or norm:match("preset%s+([%w_%-]+)") or norm:match("profil%s+([%w_%-]+)") or "default"

			return { Label = ('Load config <b>%s</b>'):format(name), Icon = "folder", Run = function()

				local ok = Library:LoadConfigFromFile(name)

				Library:Notify({ Title = "Config", Content = ok and ("Loaded " .. name .. ".") or "Config not found.", Type = ok and "success" or "error" })

			end }

		end

		if norm:find("intro") and (norm:find("replay") or norm:find("rejoue") or norm:find("relance") or norm:find("montre") or norm:find("play")) then

			return { Label = "Replay the intro", Icon = "play", Run = function()

				task.delay(0.2, function()

					if Library.Window then Library.Window:SetOpen(false, true) end

					Library.IntroPlayed = false

					Library:Intro({ Title = Library.WindowOptions and Library.WindowOptions.Title, Subtitle = Library.WindowOptions and (Library.WindowOptions.Game or Library.WindowOptions.Subtitle) })

				end)

			end }

		end

		if norm:find("unload") or norm:find("decharge") or norm:find("quitte le script") then

			return { Label = "Unload the script", Icon = "trash", Danger = true, Run = function() Library:Unload() end }

		end

		if norm == "hide" or norm:find("cache le menu") or norm:find("ferme le menu") or norm:find("close menu") or norm:find("hide menu") then

			return { Label = "Hide the menu", Icon = "close", Run = function() if Library.Window then Library.Window:SetOpen(false) end end }

		end

		if norm:find("kyoka suigetsu") or norm:find("kyouka suigetsu") or norm:find("shatter") or norm:find("brise") then

			return { Label = "ΘÅíΦè▒µ░┤µ£ê", Icon = "sparkles", Run = function()

				local vp = ViewportSize()

				local mw = math.max(vp.X, vp.Y * 1.6)

				local rect = { x = (vp.X - mw) / 2, y = (vp.Y - mw / 1.6) / 2, w = mw, h = mw / 1.6 }

				Library:PlaySound("Crack")

				local stop = FX.Cracks(rect, 870)

				task.wait(0.3)

				stop()

				Library:PlaySound("Shatter")

				FX.Flash(0.4, 0.5)

				FX.Shatter(rect, nil, true, 869)

				Library:Notify({ Title = "ΘÅíΦè▒µ░┤µ£ê", Content = "Since when were you under the impression you were using a normal hub?" })

			end }

		end



		local verb = (HasVerb(norm, VERB.off) and "off") or (HasVerb(norm, VERB.on) and "on")

			or (HasVerb(norm, VERB.toggle) and "toggle") or (HasVerb(norm, VERB.reset) and "reset")

			or (HasVerb(norm, VERB.press) and "press") or (HasVerb(norm, VERB.set) and "set")

			or (HasVerb(norm, VERB.go) and "go")

		local words = StripWords(norm)

		if #words == 0 then return nil end



		-- Navigation vers un onglet / une page.

		if verb == "go" and Library.Window then

			local best, bs = nil, 0

			for _, tab in ipairs(Library.Window.Tabs) do

				local s = Score(words, tab.Name)

				if s > bs then best, bs = { Tab = tab }, s end

				for _, p in ipairs(tab.Pages) do

					local s2 = Score(words, p.Name, tab.Name)

					if s2 > bs then best, bs = { Tab = tab, Page = p }, s2 end

				end

			end

			if best and bs >= 0.6 then

				return { Label = ('Open <b>%s</b>'):format(best.Page and (best.Tab.Name .. " ΓÇ║ " .. best.Page.Name) or best.Tab.Name), Icon = "layers", Run = function()

					best.Tab:Select()

					if best.Page then best.Page.Select() end

				end }

			end

		end



		local kinds

		if verb == "on" or verb == "off" or verb == "toggle" then kinds = { toggle = true }

		elseif verb == "press" then kinds = { button = true }

		elseif num ~= nil then kinds = { slider = true, textbox = true }

		end

		local e, s = BestEntry(words, kinds)

		if (not e or s < 0.55) and kinds then e, s = BestEntry(words) end

		if not e or s < 0.55 then return nil, words end



		local obj = e.Obj

		if e.Kind == "toggle" then

			local target = (verb == "off" and false) or (verb == "on" and true) or not obj.Value

			if verb == nil and num ~= nil then target = num ~= 0 end

			return { Entry = e, Icon = target and "success" or "error",

				Label = ('%s %s'):format(target and "Enable" or "Disable", Describe(e)),

				Run = function() obj:Set(target) end }

		elseif e.Kind == "slider" then

			if verb == "reset" then

				return { Entry = e, Icon = "refresh", Label = ('Reset %s ΓåÆ %s'):format(Describe(e), tostring(obj.Default)), Run = function() obj:Set(obj.Default) end }

			end

			if num == nil then

				if norm:find("max") then num = obj.Max elseif norm:find("min") then num = obj.Min end

			end

			if num == nil then return { Entry = e, Reveal = true, Icon = "sliders", Label = ('Show %s'):format(Describe(e)) } end

			local v = math.clamp(num, obj.Min or num, obj.Max or num)

			return { Entry = e, Icon = "sliders", Label = ('Set %s ΓåÆ <b>%s%s</b>'):format(Describe(e), tostring(K.Round(v, obj.Rounding or 0)), obj.Suffix or ""), Run = function() obj:Set(v) end }

		elseif e.Kind == "dropdown" then

			local values = obj.Values or {}

			local pick, ps = nil, 0

			for _, v in ipairs(values) do

				local sc = Score(Tokens(tostring(v)), raw) + Score(words, tostring(v)) * 0.5

				if sc > ps then pick, ps = v, sc end

			end

			if pick and ps >= 0.6 then

				return { Entry = e, Icon = "layers", Label = ('Set %s ΓåÆ <b>%s</b>'):format(Describe(e), tostring(pick)), Run = function()

					if obj.Multi then

						local list = table.clone(obj.Value or {})

						if verb == "off" then

							local i = table.find(list, pick); if i then table.remove(list, i) end

						elseif not table.find(list, pick) then table.insert(list, pick) end

						obj:Set(list)

					else

						obj:Set(pick)

					end

				end }

			end

			return { Entry = e, Reveal = true, Icon = "layers", Label = ('Show %s'):format(Describe(e)) }

		elseif e.Kind == "button" then

			return { Entry = e, Icon = "play", Label = ('Press %s'):format(Describe(e)), Danger = obj.Danger, Run = function()

				if obj.Callback then task.spawn(obj.Callback) end

			end }

		elseif e.Kind == "textbox" and num ~= nil then

			return { Entry = e, Icon = "chat", Label = ('Set %s ΓåÆ <b>%s</b>'):format(Describe(e), tostring(num)), Run = function() obj:Set(tostring(num)) end }

		end

		return { Entry = e, Reveal = true, Icon = "eye", Label = ('Show %s'):format(Describe(e)) }

	end



	local function Parse(text)

		local actions = {}

		local clauses = {}

		local s = " " .. Norm(text) .. " "

		s = s:gsub(" et puis ", " | "):gsub(" puis ", " | "):gsub(" then ", " | "):gsub(" and ", " | ")

			:gsub(" et ", " | "):gsub(" & ", " | "):gsub(" %+ ", " | "):gsub(",", " | "):gsub(";", " | ")

		for part in s:gmatch("[^|]+") do

			if part:match("%S") then table.insert(clauses, part) end

		end

		-- |½ active esp et boxes |╗ : le verbe vaut pour la suite.

		local lastVerb

		for _, c in ipairs(clauses) do

			local n = Norm(c)

			local v = HasVerb(n, VERB.off) or HasVerb(n, VERB.on) or HasVerb(n, VERB.set) or HasVerb(n, VERB.press) or HasVerb(n, VERB.toggle)

			if v then lastVerb = v elseif lastVerb then c = lastVerb .. " " .. c end

			local act = ParseClause(c)

			if act then table.insert(actions, act) end

		end

		return actions

	end

	A.Parse = Parse



