	local function SelectRow(i)

		local rows = {}

		for _, r in ipairs(A.Rows) do if not r.Caption then table.insert(rows, r) end end

		if #rows == 0 then A.Index = 1 return end

		A.Index = math.clamp(i, 1, #rows)

		for j, r in ipairs(rows) do

			local on = j == A.Index

			Tween(r.Frame, 0.12, { BackgroundTransparency = on and 0 or 1 })

			Tween(r.Bar, 0.15, { BackgroundTransparency = on and 0 or 1 })

		end

		local target = rows[A.Index].Frame

		task.defer(function()

			local top = target.AbsolutePosition.Y - Body.AbsolutePosition.Y

			local f = math.max(Factor(), 0.01)

			local h = Body.AbsoluteSize.Y

			if top < 0 then

				Body.CanvasPosition = Vector2.new(0, Body.CanvasPosition.Y + top - 8 * f)

			elseif top + target.AbsoluteSize.Y > h then

				Body.CanvasPosition = Vector2.new(0, Body.CanvasPosition.Y + top + target.AbsoluteSize.Y - h + 8 * f)

			end

		end)

		A.Selected = rows[A.Index]

	end



