	local function LiveControl(e)

		return function(holder)

			local obj = e.Obj

			if e.Kind == "toggle" and type(obj) == "table" then

				local track, set = K.Switch(holder, 30, 17)

				track.AnchorPoint = Vector2.new(1, 0.5)

				track.Position = UDim2.new(1, 0, 0.5, 0)

				set(obj.Value, true)

				e._sync = function() set(obj.Value) end

			elseif e.Kind == "slider" and type(obj) == "table" then

				local v = Mono(holder, "", 11.5, "Text", Enum.FontWeight.SemiBold)

				v.TextXAlignment = Enum.TextXAlignment.Right

				v.ZIndex = 774

				local function sync() v.Text = ("ΓÇ╣ %s%s ΓÇ║"):format(tostring(K.Round(obj.Value, obj.Rounding or 0)), obj.Suffix or "") end

				sync()

				e._sync = sync

			elseif e.Kind == "dropdown" and type(obj) == "table" then

				local v = Mono(holder, "", 10.5, "TextDim")

				v.TextXAlignment = Enum.TextXAlignment.Right

				v.TextTruncate = Enum.TextTruncate.AtEnd

				v.ZIndex = 774

				local val = obj.Value

				v.Text = type(val) == "table" and (#val .. " selected") or tostring(val or "ΓÇö")

			elseif e.Kind == "keybind" and type(obj) == "table" and obj.Value then

				local v = Mono(holder, string.upper(KeyName(obj.Value.Key)), 10.5, "TextDim", Enum.FontWeight.SemiBold)

				v.TextXAlignment = Enum.TextXAlignment.Right

				v.ZIndex = 774

			end

		end

	end



	local function Reveal(e)

		if not e or not e.Group then return end

		local page = e.Group.Page

		local tab = page and page.Tab

		A.Close()

		if Library.Window and not Library.Open then Library.Window:SetOpen(true) end

		if tab then tab:Select(true) end

		if page and page.Select then page.Select(true) end

		task.delay(0.15, function()

			local row = e.Row

			if not row or not row.Parent then return end

			local col = row:FindFirstAncestorOfClass("ScrollingFrame")

			if col then

				local top = row.AbsolutePosition.Y - col.AbsolutePosition.Y + col.CanvasPosition.Y

				col.CanvasPosition = Vector2.new(0, math.max(top - col.AbsoluteSize.Y * 0.35, 0))

			end

			local hover = row:FindFirstChild("Hover")

			if hover then

				hover.BackgroundColor3 = Theme.Accent

				hover.BackgroundTransparency = 0.7

				Tween(hover, 1.1, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad)

				task.delay(1.15, function() hover.BackgroundColor3 = Theme.ElementHover end)

			end

		end)

	end

	A.Reveal = Reveal



	local function Remember(e)

		for i = #A.Recent, 1, -1 do if A.Recent[i] == e then table.remove(A.Recent, i) end end

		table.insert(A.Recent, 1, e)

		while #A.Recent > 5 do table.remove(A.Recent) end

	end



	local function RunEntry(e, row)

		Remember(e)

		local obj = e.Obj

		if e.Kind == "command" then

			A.Close()

			task.spawn(e.Run)

		elseif e.Kind == "toggle" then

			obj:Set(not obj.Value)

			if e._sync then e._sync() end

			if row then FX.Pulse(row.Frame, Theme.Accent, 1.4) end

		elseif e.Kind == "button" then

			Library:PlaySound("Click")

			if obj.Callback then task.spawn(obj.Callback) end

			if row then FX.Pulse(row.Frame, Theme.Accent, 1.4) end

		else

			Reveal(e)

		end

	end



	local function Step(e, dir)

		if e.Kind ~= "slider" then return end

		local obj = e.Obj

		local stepSize = (10 ^ -(obj.Rounding or 0))

		local range = (obj.Max or 100) - (obj.Min or 0)

		if range / stepSize > 60 then stepSize = range / 40 end

		obj:Set((obj.Value or 0) + stepSize * dir)

		if e._sync then e._sync() end

	end



