		end

		Library:Connect(backdrop.MouseButton1Click, function()

			if os.clock() - (win.CustomizeOpenedAt or 0) > 0.3 then win:ToggleCustomize(false) end

		end)

		Library:Connect(closeBtn.MouseButton1Click, function() win:ToggleCustomize(false) end)

		Library:Connect(UserInputService.InputBegan, function(input)

			if shown and input.KeyCode == Enum.KeyCode.Escape and not (Library.Palette and Library.Palette.Shown) then

				win:ToggleCustomize(false)

			end

		end)

	end)



	--=====================================================================

	-- Dechargement

	--=====================================================================



	function Library:Unload()

		if Library.Unloaded then return end

		Library.Unloaded = true

		pcall(function() Library:ShowCursor(false) end)

		pcall(FX.ClearBlur)

		for _, conn in ipairs(Library.Connections) do pcall(function() conn:Disconnect() end) end

		table.clear(Library.Connections)

		for _, pool in pairs(SoundPool) do

			for _, s in ipairs(pool) do pcall(function() s:Destroy() end) end

		end

		table.clear(SoundPool)

		pcall(function() ScreenGui:Destroy() end)

		if Library.OnUnload then pcall(Library.OnUnload) end

	end



	return Library

end)()



