                        end
                    elseif Config.AutoQTE or (sName == "Thorian" and Config.AutoThorianQTE) then
                        task.wait(QTEDelay(rName, data))
                        return NW_BuildQTEResult(rName, data)
                    end
                    if type(data) == "table" and data.Nonce then
