-- FEATURE 4: OPTIMIZED AUTO ATTACK TURN LOOP (EVENT-DRIVEN & RELIABLE)

------------------------------------------------------------------------

local IsMyTurnActive = false

local LastAttackTurnTime = 0



-- Listen directly to server turn start/end events

pcall(function()

    local startAction = FightRemotes:WaitForChild("StartAction", 5)

    local startSummoned = FightRemotes:WaitForChild("StartSummonedAction", 5)

    local endAction = FightRemotes:WaitForChild("EndAction", 5)

    local endFight = FightRemotes:WaitForChild("EndFight", 5)



    if startAction then

        TrackConnection(startAction.OnClientEvent:Connect(function()

            IsMyTurnActive = true

        end))

    end

    if startSummoned then

        TrackConnection(startSummoned.OnClientEvent:Connect(function()

            IsMyTurnActive = true

        end))

    end

    if endAction then

        TrackConnection(endAction.OnClientEvent:Connect(function()

            IsMyTurnActive = false

        end))

    end

    if endFight then

        TrackConnection(endFight.OnClientEvent:Connect(function()

            IsMyTurnActive = false

        end))

    end

end)



task.spawn(function()

    local isExecutingAttack = false

    while task.wait(0.25) do

        if HubUnloaded then break end

        if Config.AutoUseSkill and not isExecutingAttack then

            pcall(function()

                local char = LocalPlayer.Character

                local fip = char and char:FindFirstChild("FightInProgress")

                if not fip or not fip.Value or fip.Value == "" then

                    IsMyTurnActive = false

                    return

                end



                local pgui = LocalPlayer:FindFirstChild("PlayerGui")

                local combatGui = pgui and pgui:FindFirstChild("Combat")

                local actionBG = combatGui and combatGui:FindFirstChild("ActionBG")



                -- Turn is valid if ActionBG is visible OR StartAction fired OR Deciding is hidden while in combat

                local deciding = combatGui and combatGui:FindFirstChild("Deciding")

                local isDeciding = deciding and deciding.Visible == true

                local isActionVisible = actionBG and actionBG.Visible == true



                local turnReady = IsMyTurnActive or isActionVisible

                if not turnReady and not isDeciding and combatGui and combatGui.Enabled then

                    if os.clock() - LastAttackTurnTime > 3.0 then

                        turnReady = true

                    end

                end



                if not turnReady then return end

                isExecutingAttack = true



                if not PlayerTurnInput then

                    isExecutingAttack = false

                    return

                end



                -- 1. Exact Enemy Resolution via GetOtherTeam / FightInProgress

                local target = nil

                local getTeam = Remotes:FindFirstChild("Data") and Remotes.Data:FindFirstChild("GetOtherTeam")

                local enemies = nil



                if getTeam then

                    pcall(function() enemies = getTeam:InvokeServer(fip.Value) end)

                    if (not enemies or #enemies == 0) then

                        pcall(function() enemies = getTeam:InvokeServer() end)

                    end

                end



                if enemies and #enemies > 0 then

                    -- Taunt priority

                    if char and char:FindFirstChild("Effects") and char.Effects:FindFirstChild("Taunted") then

                        local applier = char.Effects.Taunted:FindFirstChild("Applier")

                        if applier and applier.Value and applier.Value.Parent then

                            target = applier.Value

                        end

                    end

                    if not target then

                        for _, e in ipairs(enemies) do

                            if e and e.Parent then

                                local hum = e:FindFirstChildOfClass("Humanoid")

                                if not hum or hum.Health > 0 then

                                    target = e

                                    break

                                end

                            end

                        end

                        if not target then target = enemies[1] end

                    end

                end



                -- Fallback to living scan

                if not target then

                    local living = Workspace:FindFirstChild("Living")

                    local myHrp = char and char:FindFirstChild("HumanoidRootPart")

                    if living and myHrp then

                        local bestDist = 120

                        for _, e in ipairs(living:GetChildren()) do

                            if e:IsA("Model") and e ~= char and not Players:GetPlayerFromCharacter(e) then

                                local efip = e:FindFirstChild("FightInProgress")

                                local eHrp = e:FindFirstChild("HumanoidRootPart")

                                local eHum = e:FindFirstChildOfClass("Humanoid")

                                if (not efip or efip.Value == fip.Value) and eHrp and (not eHum or eHum.Health > 0) then

                                    local dist = (eHrp.Position - myHrp.Position).Magnitude

                                    if dist < bestDist then

                                        bestDist = dist

                                        target = e

                                    end

                                end

                            end

                        end

                    end

                end



                -- 2. Attack Execution

                if target and PlayerTurnInput then

                    local attacksPage = actionBG and actionBG:FindFirstChild("AttacksPage")

                    local attackScroll = attacksPage and attacksPage:FindFirstChild("Attack") and attacksPage.Attack:FindFirstChild("ScrollingFrame")



                    local myEnergy = (char and char:FindFirstChild("Status") and char.Status:FindFirstChild("Energy") and char.Status.Energy.Value) or 0

                    local Constants = nil

                    pcall(function() Constants = require(ReplicatedStorage.Constants) end)



                    local function isSkillReady(skillName)

                        if not skillName or skillName == "" then return false end

                        if skillName == "Strike" then return true end



                        if attackScroll then

                            local btn = attackScroll:FindFirstChild(skillName)

                            if not btn then return false end

                            if btn.Visible == false then return false end

                            if btn:FindFirstChild("CD") and btn.CD.Visible == true then return false end

                        end



                        if Constants and Constants.Skills and Constants.Skills[skillName] then

                            local sDef = Constants.Skills[skillName]

                            local cost = sDef.Cost or 0

                            if myEnergy < cost then return false end

                        end

                        return true

                    end



                    local moveList = {}

                    local custom = Config.CustomMove

                    if type(custom) == "string" and custom ~= "" then

                        table.insert(moveList, custom)

                    end

                    if type(Config.SelectedMoves) == "table" then

                        for _, m in ipairs(Config.SelectedMoves) do

                            if not table.find(moveList, m) then table.insert(moveList, m) end

                        end

                    elseif type(Config.SelectedMoves) == "string" and Config.SelectedMoves ~= "" then

                        if not table.find(moveList, Config.SelectedMoves) then table.insert(moveList, Config.SelectedMoves) end

                    end



                    -- Discover skill buttons directly from attacksPage if moveList is still empty

                    if #moveList == 0 and attackScroll then

                        for _, btn in ipairs(attackScroll:GetChildren()) do

                            if btn:IsA("TextButton") and btn.Name ~= "Strike" and btn.Visible then

                                table.insert(moveList, btn.Name)

                            end

                        end

                    end



                    local readyMoves = {}

                    for _, m in ipairs(moveList) do

                        if isSkillReady(m) then

                            table.insert(readyMoves, m)

                        end

                    end



                    local chosenMove = readyMoves[1] or "Strike"

                    local chosenDef = Constants and Constants.Skills and Constants.Skills[chosenMove]

                    local isSelf = chosenDef and chosenDef.SelfTarget == true

                    local attackArg = { Attacking = isSelf and char or target }



                    -- Fire attack

                    local fired = false

                    pcall(function()

                        local res = PlayerTurnInput:InvokeServer("Attack", chosenMove, attackArg)

                        if res ~= false then fired = true end

                    end)



                    if not fired and chosenMove ~= "Strike" then

                        pcall(function()

                            PlayerTurnInput:InvokeServer("Attack", "Strike", { Attacking = target })

                        end)

                    end



                    LastAttackTurnTime = os.clock()

                    IsMyTurnActive = false



                    -- Grace period after attack before checking again

                    task.wait(1.5)

                end

                isExecutingAttack = false

            end)

            isExecutingAttack = false

        end

    end

end)



-- FEATURE 5: SUBTERRANEAN ANTI-MOB ANTI-VOID TWEEN ENGINE

------------------------------------------------------------------------

local ActiveTween = nil

local IsTweening = false

local CurrentBV = nil



local function DisableEncounterBoxes()

    -- NOTE: CanTouch is client-side only and does NOT replicate: server-side

    -- encounter checks (regions) still apply. Best effort, not immunity.

    pcall(function()

        local encounters = Workspace:FindFirstChild("Encounters") or Workspace:FindFirstChild("EncounterZones")

        if encounters then

            for _, box in ipairs(encounters:GetDescendants()) do

                if box:IsA("BasePart") and (box.Name:find("Encounter") or box.Name:find("Zone")) then

                    box.CanTouch = false

                end

            end

        end

        local mobs = Workspace:FindFirstChild("Living") or Workspace:FindFirstChild("NPCs")

        if mobs then

            for _, mob in ipairs(mobs:GetChildren()) do

                if mob ~= LocalPlayer.Character and mob:FindFirstChild("HumanoidRootPart") then

                    mob.HumanoidRootPart.CanTouch = false

                    for _, p in ipairs(mob:GetDescendants()) do

                        if p:IsA("BasePart") and p.Name:find("Hitbox") then

                            p.CanTouch = false

                        end

                    end

                end

            end

        end

    end)

end



local function SetCharCollision(char, enabled)

    if not char then return end

    for _, part in ipairs(char:GetDescendants()) do

        if part:IsA("BasePart") then

            pcall(function()

                part.CanTouch = enabled

                if enabled then

                    if part.Name ~= "HumanoidRootPart" then

                        part.CanCollide = true

                    end

                else

                    part.CanCollide = false

                end

            end)

        end

    end

end



local function CancelTween()

    if ActiveTween then

        ActiveTween:Cancel()

        ActiveTween = nil

    end

    IsTweening = false

    if CurrentBV then

        CurrentBV:Destroy()

        CurrentBV = nil

    end

    local char = LocalPlayer.Character

    if char then

        if char:FindFirstChild("Humanoid") then

            char.Humanoid.PlatformStand = false

        end

        SetCharCollision(char, true)

    end

end



-- Anti-Fall Damage Shield: Neutralizes client-side fall damage telemetry

local function ProtectFromFallDamage(char)

    if not char then return end

    local hum = char:FindFirstChildOfClass("Humanoid")

    if hum and type(getconnections) == "function" then

        pcall(function()

            for _, c in ipairs(getconnections(hum.StateChanged)) do

                local f = c.Function

                if f and type(getupvalues) == "function" and type(setupvalue) == "function" then

                    pcall(function()

                        for i, uv in ipairs(getupvalues(f)) do

                            if type(uv) == "function" and debug.info(uv, "n") == "damagecheck" then

                                setupvalue(f, i, function() end)

                            end

                        end

                    end)

                end

                if f and type(getfenv) == "function" then

                    local env = getfenv(f)

                    if type(rawget(env, "damagecheck")) == "function" then

                        rawset(env, "damagecheck", function() end)

                    end

                end

            end

        end)

    end

end



-- Proteger immediatement le personnage actuel et ├á chaque respawn

if LocalPlayer and LocalPlayer.Character then

    ProtectFromFallDamage(LocalPlayer.Character)

end

if LocalPlayer then

    TrackConnection(LocalPlayer.CharacterAdded:Connect(function(newChar)

        task.wait(0.5)

        ProtectFromFallDamage(newChar)

    end))

end



-- Anti-Encounter Safe Navigation (Underground Subterranean + Touch Neutralizer)

local function SafeTweenTo(targetCFrame, onComplete)

    local char = LocalPlayer.Character

    if not char then return end

    local hrp = char:FindFirstChild("HumanoidRootPart")

    local hum = char:FindFirstChild("Humanoid")

    if not hrp or not hum then return end



    CancelTween()

    IsTweening = true

    ProtectFromFallDamage(char)

    hum.PlatformStand = false



    -- 1. Neutralize all Encounter and Mob Touch Triggers immediately

    DisableEncounterBoxes()

    SetCharCollision(char, false)



    local startPos = hrp.Position

    local endPos = typeof(targetCFrame) == "CFrame" and targetCFrame.Position or targetCFrame



    if type(LocalPlayer.RequestStreamAroundAsync) == "function" then

        pcall(function() LocalPlayer:RequestStreamAroundAsync(endPos, 5) end)

    end



    local groundTarget = endPos

    local totalDist = (groundTarget - startPos).Magnitude

    local speed = math.clamp(tonumber(Config.TweenSpeed) or 28, 16, 35)



    -- Continuous Anti-Touch & Anti-Encounter Enforcement during movement

    local touchWatchdog = RunService.Stepped:Connect(function()

        if not IsTweening or HubUnloaded then return end

        local c = LocalPlayer.Character

        if c then

            for _, p in ipairs(c:GetDescendants()) do

                if p:IsA("BasePart") then

                    p.CanTouch = false

                    p.CanCollide = false

                end

            end

        end

    end)



    local cancelled = false



    local function finalizeArrival()

        if touchWatchdog then touchWatchdog:Disconnect() end

        if cancelled or HubUnloaded then

            CancelTween()

            return

        end

        hrp.CFrame = CFrame.new(groundTarget)

        hrp.AssemblyLinearVelocity = Vector3.zero

        task.wait(0.08)

        ProtectFromFallDamage(char)

        if onComplete then

            pcall(onComplete)

        end

        CancelTween()

    end



    -- Abort immediately if player enters combat

    task.spawn(function()

        while IsTweening and not HubUnloaded do

            task.wait(0.25)

            local c = LocalPlayer.Character

            if c and c:FindFirstChild("FightInProgress") and c.FightInProgress.Value ~= "" then

                cancelled = true

                if touchWatchdog then touchWatchdog:Disconnect() end

                CancelTween()

                break

            end

        end

    end)



    -- Direct glide: safe from void and collision traps, bypasses all encounters via CanTouch = false

    local duration = math.clamp(totalDist / speed, 0.35, 45.0)

    local tween = TweenService:Create(hrp, TweenInfo.new(duration, Enum.EasingStyle.Linear), { CFrame = CFrame.new(groundTarget) })

    ActiveTween = tween

    tween.Completed:Connect(function()

        finalizeArrival()

    end)

    tween:Play()



    local maxFlightTime = duration + 5.0

    task.delay(maxFlightTime, function()

        if IsTweening and ActiveTween then

            finalizeArrival()

        end

    end)

end



