                        if cd and type(fireclickdetector) == "function" and myHrp1 then

                            myHrp1.CFrame = CFrame.new(bestPart.Position + Vector3.new(0, 3, 0))

                            task.wait(0.3)

                            fireclickdetector(cd, 0)

                            task.wait(0.1)

                            fireclickdetector(cd, 0)

                        end

                    end)

                end

            end)

        end

    end

end)



