local function isRealCarvedPumpkin(obj, collected)

    if not (obj and obj:IsA("Model")) or Players:GetPlayerFromCharacter(obj) then return false end

    local name = obj.Name

    if collected and (collected[name] or (typeof(obj) == "Instance" and collected[obj])) then return false end



    -- Real pumpkins always have randomized alphanumeric names (at least 6 alphanumeric chars, no dictionary words)

    if #name < 6 or not name:match("^[A-Za-z0-9]+$") then return false end

    local lowerName = name:lower()

    if lowerName:find("candle") or lowerName:find("door") or lowerName:find("gate") or lowerName:find("chest") or lowerName:find("curve") then

        return false

    end



    local hasLight = false

    local hasNeon = false

    local hasWood = false

    local partCount = 0



    for _, d in ipairs(obj:GetChildren()) do

        if d:IsA("BasePart") then

            partCount += 1

            if d:FindFirstChildWhichIsA("PointLight") then hasLight = true end

            if d.Material == Enum.Material.Neon then hasNeon = true end

            if d.Material == Enum.Material.Wood or d.Material == Enum.Material.WoodPlanks

               or d.BrickColor.Name:find("Brown") or d.BrickColor.Name:find("brown")

               or d.BrickColor.Name:find("orange") or d.BrickColor.Name:find("Sienna") or d.BrickColor.Name:find("Cocoa") then

                hasWood = true

            end

        end

    end



    return hasLight and hasNeon and hasWood and partCount >= 4

end



local function getUncollectedPumpkins()

    local hInfo = InfoRemotes:FindFirstChild("HalloweenInfo")

    local collected = {}

    if hInfo and type(getconnections) == "function" then

        local conns = getconnections(hInfo.OnClientEvent)

        if #conns > 0 and type(getupvalues) == "function" then

            local uvs = getupvalues(conns[1].Function)

            if uvs and uvs[6] and type(uvs[6]) == "table" then

                collected = uvs[6]

            end

        end

    end



    local valid = {}

    for _, obj in ipairs(Workspace:GetChildren()) do

        if isRealCarvedPumpkin(obj, collected) then

            table.insert(valid, obj)

        end

    end

    return valid

end



task.spawn(function()

    while task.wait(1.5) do

        if HubUnloaded then break end



        if Config.AutoHalloweenPumpkins and not IsTweening then

            pcall(function()

                local char = LocalPlayer.Character

                if char and char:FindFirstChild("FightInProgress") then return end

                local hrp = char and char:FindFirstChild("HumanoidRootPart")

                if not hrp then return end



                local uncollected = getUncollectedPumpkins()

                local targetModel = nil

                local targetPos = nil



                if #uncollected > 0 then

                    -- Sort by nearest to player

                    local myPos = hrp.Position

                    table.sort(uncollected, function(a, b)

                        return (a:GetPivot().Position - myPos).Magnitude < (b:GetPivot().Position - myPos).Magnitude

                    end)

                    targetModel = uncollected[1]

                    targetPos = targetModel:GetPivot().Position

                else

                    -- Fallback: If models not streamed in, scan static coordinates for uncollected locations

                    local myPos = hrp.Position

                    local bestDist = 999999

                    for _, coord in ipairs(ALL_24_PUMPKIN_COORDS) do

                        local dist = (coord - myPos).Magnitude

                        if dist > 35 and dist < bestDist then

                            bestDist = dist

                            targetPos = coord

                        end

                    end

                end



                if not targetPos then return end



                local savedSpeed = Config.TweenSpeed

                Config.TweenSpeed = 30



                local targetCF = CFrame.new(targetPos + Vector3.new(0, 1.2, 0))

                SafeTweenTo(targetCF, function()

                    Config.TweenSpeed = savedSpeed



                    local cNow = LocalPlayer.Character

                    if not cNow or cNow:FindFirstChild("FightInProgress") then return end



                    local root = cNow:FindFirstChild("HumanoidRootPart")

                    local hum = cNow:FindFirstChild("Humanoid")

                    if not root or not hum then return end



                    -- If we traveled to a static coordinate, find the model that streamed in

                    if not targetModel or not targetModel.Parent then

                        local found = getUncollectedPumpkins()

                        if #found > 0 then

                            table.sort(found, function(a, b)

                                return (a:GetPivot().Position - root.Position).Magnitude < (b:GetPivot().Position - root.Position).Magnitude

                            end)

                            targetModel = found[1]

                        end

                    end



                    if not targetModel or not targetModel.Parent then

                        task.wait(0.5)

                        return

                    end



                    local curDist = (root.Position - targetModel:GetPivot().Position).Magnitude

                    if curDist > 20 then return end



                    -- Ensure character is fully grounded, stationary and active

                    hum.PlatformStand = false

                    root.AssemblyLinearVelocity = Vector3.zero

                    task.wait(0.2)



                    -- Trigger client setNear to generate the ProximityPrompt

                    local hInfo = InfoRemotes:FindFirstChild("HalloweenInfo")

                    if hInfo and type(getconnections) == "function" then

                        pcall(function()

                            local conns = getconnections(hInfo.OnClientEvent)

                            if #conns > 0 and type(getupvalues) == "function" then

                                local uvs = getupvalues(conns[1].Function)

                                local setNear = uvs and uvs[5]

                                if type(setNear) == "function" then

                                    setNear({ targetModel })

                                end

                            end

                        end)

                    end



                    task.wait(0.4)



                    local pp = targetModel:FindFirstChildWhichIsA("ProximityPrompt", true)

                    if pp then

                        pp.Enabled = true

                        pcall(function()

                            pp:InputHoldBegin()

                            task.wait((pp.HoldDuration or 0.35) + 0.1)

                            pp:InputHoldEnd()

                        end)

                        if type(fireproximityprompt) == "function" then

                            pcall(function() fireproximityprompt(pp, pp.HoldDuration or 0.35) end)

                        end

                    end



                    if hInfo then

                        NW_SafeFireServer(hInfo, "Pick", targetModel)

                    end



                    task.wait(1.0)

                end)

            end)

        end

    end

end)



-- Dedicated Continuous NPC Dialogue Engine

-- Scans NPCDialogue at human pace (0.6s), cleanly handles progression and stops loops

local NPCInteractCooldowns = {}

local LastDialogueActionTime = 0



local function SetNPCCooldown(name, duration)

    if not name then return end

    NPCInteractCooldowns[name:lower()] = os.clock() + (duration or 4)

end



local function IsNPCOnCooldown(name)

    if not name then return false end

    local exp = NPCInteractCooldowns[name:lower()]

    return exp and os.clock() < exp

end



task.spawn(function()

    while task.wait(0.6) do

        if HubUnloaded then break end

        pcall(function()

            local pgui = LocalPlayer:FindFirstChild("PlayerGui")

            local diag = pgui and pgui:FindFirstChild("NPCDialogue")

            if diag and diag.Enabled then

                local bg = diag:FindFirstChild("BG")

                local rem = diag:FindFirstChild("RemoteEvent")

                local talkLabel = bg and (bg:FindFirstChild("Dialogue") and bg.Dialogue:FindFirstChild("Talk") or bg:FindFirstChild("Talk"))

                local talkText = talkLabel and talkLabel.Text:lower() or ""

                local npcNameLabel = bg and bg:FindFirstChild("NPCName")

                local npcName = npcNameLabel and npcNameLabel.Text or "Unknown"



                local function ClickDialogueButton(btn)

                    if not btn then return end

                    pcall(function()

                        if type(getconnections) == "function" then

                            for _, c in ipairs(getconnections(btn.MouseButton1Click)) do c:Fire() end

                            for _, c in ipairs(getconnections(btn.Activated)) do c:Fire() end

                        end

                        if type(firesignal) == "function" then

                            pcall(function() firesignal(btn.MouseButton1Click) end)

                            pcall(function() firesignal(btn.Activated) end)

                        end

                    end)

                end



                -- Instant Farewell / Exit Detection (Break a leg, goodbye, farewell, etc.)

                if talkText:find("break a leg") or talkText:find("farewell") or talkText:find("see you") or talkText:find("good luck") then

                    SetNPCCooldown(npcName, 30)

                    if rem then

                        pcall(function() NW_SafeFireServer(rem, { Text = "Leave." }) end)

                    end

                    local opts = bg and bg:FindFirstChild("Options")

                    if opts then

                        for _, c in ipairs(opts:GetChildren()) do

                            if c:IsA("TextButton") and c.Visible and c.Text:lower():find("leave") then

                                ClickDialogueButton(c)

                                break

                            end

                        end

                    end

                    return

                end



                if os.clock() - LastDialogueActionTime < 0.6 then return end



                if bg then

                    local opts = bg:FindFirstChild("Options")

                    local chosen = nil

                    if opts then

                        local valid = {}

                        local leaveBtn = nil

                        for _, c in ipairs(opts:GetChildren()) do

                            if c:IsA("TextButton") and c.Visible then

                                if c.Text:lower():find("leave") then

                                    leaveBtn = c

                                else

                                    table.insert(valid, c)

                                end

                            end

                        end



                        -- Duraelis: NEVER loop dialogue. If leave exists, immediately leave and cool down!

                        if npcName:lower():find("duraelis") then

                            if leaveBtn then

                                chosen = leaveBtn

                                SetNPCCooldown("Duraelis", 120)

                            end

                        elseif #valid > 0 then

                            for _, v in ipairs(valid) do

                                local t = v.Text:lower()

                                if t:find("halloween") or t:find("dead") or t:find("quest")

                                   or t:find("next") or t:find("begin") or t:find("continue") or t:find("rift")

                                   or t:find("flyer") or t:find("theater") or t:find("gate") or t:find("whistle")

                                   or t:find("head to") or t:find("take the") or t:find("so who") or t:find("where do") then

                                    chosen = v

                                    break

                                end

                            end



                            if not chosen then

                                if leaveBtn then

                                    chosen = leaveBtn

                                    SetNPCCooldown(npcName, 30)

                                else

                                    chosen = valid[1]

                                end

                            end

                        elseif leaveBtn then

                            chosen = leaveBtn

                            SetNPCCooldown(npcName, 30)

                        end

                    end



                    if chosen then

                        LastDialogueActionTime = os.clock()

                        if rem then

                            NW_SafeFireServer(rem, { Text = chosen.Text })

                        end

                        ClickDialogueButton(chosen)

                        if chosen.Text:lower():find("leave") then

                            SetNPCCooldown(npcName, 30)

                        end

                    else

                        local skip = bg:FindFirstChild("Skip")

                        if skip and skip.Visible then

                            LastDialogueActionTime = os.clock()

                            ClickDialogueButton(skip)

                        end

                    end

                end

            end

        end)

    end

end)



