local tagConnections = {}



local function CreatePlayerTag(player)

    if player ~= LocalPlayer then return end

    local function applyTag(character)

        if not character then return end

        local head = character:WaitForChild("Head", 5)

        if not head then return end



        -- Remove old tag from head (legacy cleanup ΓÇö was replicating to all players)

        local old = head:FindFirstChild("NW_HUB_Tag")

        if old then old:Destroy() end



        -- Parent to gethui/CoreGui so it's CLIENT-ONLY (not replicated)

        local safeParent

        pcall(function() safeParent = gethui() end)

        if not safeParent then

            pcall(function() safeParent = game:GetService("CoreGui") end)

        end

        if not safeParent then return end



        local billboard = Instance.new("BillboardGui")

        billboard.Name = "NW_HUB_Tag"

        billboard.Adornee = head

        billboard.Size = UDim2.fromOffset(220, 50)

		billboard.MaxDistance = 100

        billboard.StudsOffset = Vector3.new(0, 1.2, 0)

        billboard.AlwaysOnTop = false

        billboard.ResetOnSpawn = false

        billboard.Parent = safeParent





        local label = Instance.new("TextLabel")

        label.Size = UDim2.fromScale(1, 1)

        label.BackgroundTransparency = 1

        label.Text = "NW HUB"

        label.TextSize = 17

        label.FontFace = Font.new(

            "rbxasset://fonts/families/BuilderExtended.json",

            Enum.FontWeight.ExtraBold,

            Enum.FontStyle.Normal

        )

        label.TextStrokeTransparency = 0

        label.TextStrokeColor3 = Color3.new(0, 0, 0)

        label.ZIndex = 2

        label.Parent = billboard



        local stroke = Instance.new("UIStroke")

        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual

        stroke.Thickness = 2

        stroke.Parent = label



		        local cam = workspace.CurrentCamera

        local scaleConn = RunService.RenderStepped:Connect(function()

            if not label.Parent then return end

            local dist = (cam.CFrame.Position - billboard.Adornee.Position).Magnitude

            local scale = math.clamp(20 / math.max(dist, 1), 0.3, 2)

            label.TextSize = math.floor(28 * scale)

            stroke.Thickness = math.clamp(2 * scale, 0.5, 4)

        end)

        table.insert(tagConnections, scaleConn)



		

        -- RGB rainbow loop on this specific label

        local hue = math.random()

        local conn = RunService.Heartbeat:Connect(function(dt)

            if not label.Parent then return end

            hue = (hue + dt * 0.55) % 1

            local color = Color3.fromHSV(hue, 1, 1)

            label.TextColor3 = color

            label.TextStrokeColor3 = color:Lerp(Color3.new(0, 0, 0), 0.6)

        end)

        table.insert(tagConnections, conn)

    end



    applyTag(player.Character)

    local conn = player.CharacterAdded:Connect(applyTag)

    table.insert(tagConnections, conn)

end



