local ESPCache = {}



-- Deterministic part pick: FindFirstChildWhichIsA order is NOT stable across

-- calls, so re-picking every refresh created one billboard per part over time.

-- GetChildren order is stable: same item -> same part -> cache hit.

local function ItemPart(item)

    if item:IsA("BasePart") then return item end

    local fallback = nil

    for _, c in ipairs(item:GetChildren()) do

        if c:IsA("BasePart") then

            if c.Name == "Handle" or c.Name == "HumanoidRootPart" or c.Name == "ClickPart" then

                return c

            end

            fallback = fallback or c

        end

    end

    if fallback then return fallback end

    return item:FindFirstChildWhichIsA("BasePart", true)

end



-- =====================================================================
-- CATEGORIZED ESP ENGINE WITH INSTANT CLEANUP ON UNTOGGLE
-- =====================================================================
local ESPCache = {} -- [inst] = { Gui = BillboardGui, Category = string }

local function ClearESPCategory(category)
    for inst, data in pairs(ESPCache) do
        if not category or data.Category == category then
            if data.Gui then
                pcall(function() data.Gui:Destroy() end)
            end
            ESPCache[inst] = nil
        end
    end
end

local function EnsureESP(inst, text, color, size, category)
    if not inst then return end
    category = category or "Other"
    local entry = ESPCache[inst]
    if not entry or not entry.Gui or not entry.Gui.Parent then
        local gui = Instance.new("BillboardGui")
        gui.Name = "NW_ESP_" .. category
        gui.Adornee = inst
        gui.Size = size or UDim2.new(0, 100, 0, 25)
        gui.AlwaysOnTop = true
        gui.Parent = ESPFolder

        local label = Instance.new("TextLabel")
        label.Name = "L"
        label.Size = UDim2.new(1, 0, 1, 0)
        label.BackgroundTransparency = 1
        label.TextColor3 = color or Color3.fromRGB(255, 255, 255)
        label.TextStrokeTransparency = 0
        label.TextSize = 12
        label.Font = Enum.Font.GothamBold
        label.Parent = gui

        entry = { Gui = gui, Category = category }
        ESPCache[inst] = entry
    end
    entry.Category = category
    if entry.Gui and entry.Gui:FindFirstChild("L") then
        entry.Gui.L.Text = text
    end
end

local function SweepESP()
    for inst, data in pairs(ESPCache) do
        if not inst or not inst.Parent or not data.Gui or not data.Gui.Parent then
            if data.Gui then pcall(function() data.Gui:Destroy() end) end
            ESPCache[inst] = nil
        end
    end
end

local function RefreshESP()
    local myHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")

    -- 1. Items ESP
    if Config.ESPItems then
        local folder = Workspace:FindFirstChild("SpawnedItems")
        if folder then
            for _, item in ipairs(folder:GetChildren()) do
                local part = ItemPart(item)
                if part then
                    local dist = myHrp and math.floor((part.Position - myHrp.Position).Magnitude) or 0
                    EnsureESP(part, item.Name .. "\n[" .. dist .. "m]", Color3.fromRGB(80, 255, 120), UDim2.new(0, 100, 0, 25), "Items")
                end
            end
        end
    end

    -- 2. Players ESP
    if Config.ESPPlayers then
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character then
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local dist = myHrp and math.floor((hrp.Position - myHrp.Position).Magnitude) or 0
                    EnsureESP(hrp, p.DisplayName .. "\n[" .. dist .. "m]", Color3.fromRGB(255, 80, 80), UDim2.new(0, 120, 0, 35), "Players")
                end
            end
        end
    end

    -- 3. Merchants ESP
    if Config.ESPMerchants then
        local buyables = Workspace:FindFirstChild("Mechanical") and Workspace.Mechanical:FindFirstChild("Buyables")
        if buyables then
            for _, b in ipairs(buyables:GetChildren()) do
                local part = b:FindFirstChild("HumanoidRootPart") or b:FindFirstChildWhichIsA("BasePart")
                if part then
                    local dist = myHrp and math.floor((part.Position - myHrp.Position).Magnitude) or 0
                    EnsureESP(part, "[Merchant] " .. b.Name .. "\n[" .. dist .. "m]", Color3.fromRGB(255, 215, 0), UDim2.new(0, 140, 0, 35), "Merchants")
                end
            end
        end

        local npcs = Workspace:FindFirstChild("NPCs")
        if npcs then
            for _, mName in ipairs({"Merchant", "Merchant1"}) do
                local m = npcs:FindFirstChild(mName)
                local part = m and (m:FindFirstChild("HumanoidRootPart") or m:FindFirstChildWhichIsA("BasePart"))
                if part then
                    local dist = myHrp and math.floor((part.Position - myHrp.Position).Magnitude) or 0
                    EnsureESP(part, "[Merchant] " .. m.Name .. "\n[" .. dist .. "m]", Color3.fromRGB(255, 215, 0), UDim2.new(0, 140, 0, 35), "Merchants")
                end
            end
            local tgMerchants = npcs:FindFirstChild("TundraGate") and npcs.TundraGate:FindFirstChild("Merchants")
            if tgMerchants then
                for _, m in ipairs(tgMerchants:GetChildren()) do
                    local part = m:FindFirstChild("HumanoidRootPart") or m:FindFirstChildWhichIsA("BasePart")
                    if part then
                        local dist = myHrp and math.floor((part.Position - myHrp.Position).Magnitude) or 0
                        EnsureESP(part, "[Merchant] " .. m.Name .. "\n[" .. dist .. "m]", Color3.fromRGB(255, 215, 0), UDim2.new(0, 140, 0, 35), "Merchants")
                    end
                end
            end
        end
    end

    -- 4. 24 Event Carved Pumpkins ESP
    if Config.ESPPumpkins then
        local uncollected = getUncollectedPumpkins()
        for idx, pInfo in ipairs(uncollected) do
            local targetPart = pInfo.Instance and (pInfo.Instance:FindFirstChild("Part") or pInfo.Instance:FindFirstChildWhichIsA("BasePart"))
            if not targetPart and pInfo.Position then
                -- Static Anchor Part for streaming-out fallback
                local anchorName = "PumpkinAnchor_" .. tostring(idx)
                local anchor = ESPFolder:FindFirstChild(anchorName)
                if not anchor then
                    anchor = Instance.new("Part")
                    anchor.Name = anchorName
                    anchor.Size = Vector3.new(2, 2, 2)
                    anchor.Position = pInfo.Position
                    anchor.Anchored = true
                    anchor.CanCollide = false
                    anchor.Transparency = 1
                    anchor.Parent = ESPFolder
                end
                targetPart = anchor
            end
            if targetPart then
                local dist = myHrp and math.floor((targetPart.Position - myHrp.Position).Magnitude) or 0
                EnsureESP(targetPart, "[🎃 Event Pumpkin]\n[" .. dist .. "m]", Color3.fromRGB(255, 140, 0), UDim2.new(0, 120, 0, 35), "Pumpkins")
            end
        end
    end
end

