local HorseCFG = {
    MaxRetries = 6,
    QuestRetry = 8,
    QuestTimeout = 300,
    BoardOffset = Vector3.new(5, 0, 0),
}

local horseState = {
    questActive = false,
    questSince = 0,
    finishedAt = 0,
    lastClick = 0,
    completed = 0,
    questText = "Idle",
    raceText = "Waiting",
}
