local Attr = (okReq and type(HS) == "table" and HS.Race) and HS.Race.Attributes or nil
local GateRemote = (okReq and type(HS) == "table" and HS.Remote) and InfoRemotes:FindFirstChild(HS.Remote) or nil

local function raceActive()
    if not Attr then return false end
    return type(LocalPlayer:GetAttribute(Attr.Gate)) == "number"
        and type(LocalPlayer:GetAttribute(Attr.Gates)) == "number"
        and type(LocalPlayer:GetAttribute(Attr.Place)) == "string"
end

local function coursesFolder()
    if not Gates or not Gates.CoursePath then return nil end
    local f = Workspace
    for _, name in ipairs(Gates.CoursePath) do
        f = f and f:FindFirstChild(name)
    end
    return f
end

local function findCourse(folder, place)
    if not folder or type(place) ~= "string" then return nil end
    for _, child in ipairs(folder:GetChildren()) do
        if child.Name == place or child:GetAttribute("Label") == place then
            return child
        end
    end
    return nil
end

-- Auto accept horse quest using SafeTweenTo
local function findHorseQuestPaper()
    local board = Workspace:FindFirstChild("QuestBoards")
    local hwBoard = board and board:FindFirstChild("Halloween")
    local hwModel = hwBoard and hwBoard:FindFirstChild("Board")
    local papers = hwModel and hwModel:FindFirstChild("Papers")
    local paper = papers and papers:FindFirstChild("HW_HorseRace")
    if paper and paper:FindFirstChildOfClass("ClickDetector") then return paper end

    if board then
        for _, b in ipairs(board:GetChildren()) do
            local pFolder = b:FindFirstChild("Board") and b.Board:FindFirstChild("Papers")
            if pFolder then
                local p = pFolder:FindFirstChild("HW_HorseRace")
                if p and p:FindFirstChildOfClass("ClickDetector") then return p end
            end
        end
    end

    local hwNpc = Workspace:FindFirstChild("NPCs") and Workspace.NPCs:FindFirstChild("Quest") and Workspace.NPCs.Quest:FindFirstChild("Halloween")
    if hwNpc then
        for _, d in ipairs(hwNpc:GetDescendants()) do
            if d.Name == "HW_HorseRace" and d:FindFirstChildOfClass("ClickDetector") then return d end
        end
    end
    return nil
end

local function acceptHorseQuest()
    horseState.lastClick = tick()
    local paper = findHorseQuestPaper()
    if not paper then
        horseState.questText = "Waiting for quest paper..."
        return
    end

    local cd = paper:FindFirstChildOfClass("ClickDetector")
    if not cd then return end

    horseState.questText = "Traveling to quest board..."
    SafeTweenTo(paper.Position + HorseCFG.BoardOffset, function()
        task.wait(0.3)
        if typeof(fireclickdetector) == "function" then
            pcall(fireclickdetector, cd)
        end
        horseState.questText = "Quest accepted!"
        horseState.questActive = true
        horseState.questSince = tick()
    end)
end

local function runHorseRace()
    if horseBusy or not Gates or not Attr or not GateRemote then return end
    horseBusy = true

    local place = LocalPlayer:GetAttribute(Attr.Place)
    local course = findCourse(coursesFolder(), place)
    if not course then
        horseState.raceText = "Course not found"
        horseBusy = false
        return
    end

    local retries, lastGate = 0, nil

    while not HubUnloaded and Config.AutoHorseRace and raceActive() do
        if LocalPlayer:GetAttribute(Attr.Place) ~= place then break end

        local gate = LocalPlayer:GetAttribute(Attr.Gate)
        local total = LocalPlayer:GetAttribute(Attr.Gates)
        horseState.raceText = tostring(place) .. " " .. tostring(gate) .. "/" .. tostring(total)

        if gate == lastGate then
            retries = retries + 1
            if retries > HorseCFG.MaxRetries then
                horseState.raceText = "Stuck gate " .. tostring(gate)
                Config.AutoHorseRace = false
                break
            end
        else
            retries, lastGate = 0, gate
        end

        local marker = course:FindFirstChild(tostring(gate))
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")

        if marker and marker:IsA("BasePart") and root then
            local targetCF = marker.CFrame * CFrame.new(0, (Gates.Height or 22) / 2, 0)
            
            -- Navigation 100% safe vers la porte
            SafeTweenTo(targetCF.Position, function()
                task.wait(0.2)
                pcall(function() GateRemote:FireServer(Gates.Remote, gate) end)
            end)
            task.wait(0.4)
        else
            task.wait(0.5)
        end
    end

    horseBusy = false
    horseState.raceText = "Waiting"
end

-- Horse Auto Loops
task.spawn(function()
    while task.wait(1.5) do
        if HubUnloaded then break end
        if Config.AutoHorseQuest and not IsTweening and not horseBusy then
            if not raceActive() and (tick() - horseState.lastClick) >= HorseCFG.QuestRetry then
                pcall(acceptHorseQuest)
            end
        end
    end
end)

task.spawn(function()
    while task.wait(0.5) do
        if HubUnloaded then break end
        if Config.AutoHorseRace and raceActive() and not horseBusy and not IsTweening then
            pcall(runHorseRace)
        end
    end
end)

