-- Clean shutdown
Kyoka.OnUnload = function()
    HubUnloaded = true
    getgenv().NWHub_RefreshSkills = nil
    getgenv().NW_HubUnload = nil
    ClearESPCategory()
    for _, conn in ipairs(HubConnections) do
        pcall(function() conn:Disconnect() end)
    end
    table.clear(HubConnections)
    for _, conn in pairs(tagConnections) do
        pcall(function() conn:Disconnect() end)
    end
    table.clear(tagConnections)
    for _, player in ipairs(Players:GetPlayers()) do
        pcall(function()
            local char = player.Character
            local head = char and char:FindFirstChild("Head")
            local tag = head and head:FindFirstChild("NW_HUB_Tag")
            if tag then tag:Destroy() end
        end)
    end
end

Kyoka:Notify({
    Title = "NW Hub",
    Content = "Arcane Lineage Clean Edition Loaded! [RightShift] to toggle.",
    Duration = 5,
    Type = "success"
})
    end
    _nw_exec(...)
end
